Add the single mirror of JS_ToStringInternal's string cases (quickjs.c:13593-13598 + 4829-4863):

pub fn linearizedStringDup(value: JSValue) !JSValue {
    // qjs JS_ToStringInternal: JS_TAG_STRING -> JS_DupValue;
    // JS_TAG_STRING_ROPE -> js_linearize_string_rope (quickjs.c:13595-13598).
    // flatten() is zjs's js_linearize_string_rope adaptation (string.zig:148):
    // O(1) when already linearized, mutates the node for O(1) revisits.
    if (value.ropeBody()) |node| {
        const flat = try node.flatten();
        return flat.value().dup();
    }
    return value.dup();
}

(caller guarantees value.isString(); assert in debug).

