Add the js_string_eq mirror, outlined like qjs's real function (gdb saw js_string_eq.isra.0 as a call from JS_CallInternal):

pub noinline fn flatStringBodiesEq(a: *const String, b: *const String) bool {
    if (a.len_meta.len != b.len_meta.len) return false; // qjs:4607
    if (a == b) return true;                            // qjs:4609
    if (a.len_meta.is_wide == b.len_meta.is_wide) {     // js_string_memcmp same-width legs
        const n = @as(usize, a.len_meta.len) << @intFromBool(a.len_meta.is_wide);
        return std.mem.eql(u8, a.inlineBytesPtr()[0..n], b.inlineBytesPtr()[0..n]); // vectorized eqlBytes = memcmp==0
    }
    const wide = if (a.len_meta.is_wide) a else b;      // memcmp16_8 leg, qjs:4595/4598
    const narrow = if (a.len_meta.is_wide) b else a;
    return eqlUtf16Latin1(wide.utf16(), narrow.latin1()); // already exists, string.zig:1596
}

(inlineBytesPtr is currently private at string.zig:708 — either place the fn inside String or expose a same-width bytes accessor; same-width byte-eql is valid for u16 equality since equality is order-insensitive.)

