Note: this is comptime-split per opcode, so the four relational handlers are byte-identical to today. Calls from hot handlers are an accepted pattern (op_define_field:3596, op_object:3575). eq (non-strict) on string×string is spec-identical to strict — qjs uses the same js_string_eq in both macros.

Kill the double scan (std.mem.eql THEN std.mem.order re-scans scalar from 0 on mismatch). qjs's single memcmp sign IS the ordering (js_string_memcmp/js_string_compare, qjs:4586-4631). zjs links glibc (BASELINE profile shows _int_malloc), so the u8 leg uses libc memcmp's sign; the u16 leg mirrors qjs's scalar memcmp16:

extern "c" fn memcmp(a: ?*const anyopaque, b: ?*const anyopaque, n: usize) c_int;

fn compareSameWidth(comptime T: type, a: []const T, b: []const T) i32 {
    const n = @min(a.len, b.len);
    if (T == u8) {
        const r = memcmp(a.ptr, b.ptr, n);          // qjs:4592 — sign is the order
        if (r != 0) return if (r < 0) -1 else 1;
    } else {
        for (a[0..n], b[0..n]) |x, y| {              // qjs memcmp16, per-unit (byte memcmp is WRONG for LE u16 order)
            if (x != y) return if (x < y) -1 else 1;
        }
    }
    return compareLength(a.len, b.len);
}

B2 — add the threshold gate mirroring qjs OP_add_loc's flat regime (qjs:19767-19772 -> JS_ConcatString qjs:5070-5075). Single choke point: both call sites (vm_arith.zig:679 addLocalString, :791 addLocalStringAt) go through here.

pub fn startAccumulatorRope(rt: *core.JSRuntime, lhs: core.JSValue, rhs: core.JSValue) !?core.JSValue {
    if (lhs.ropeBody() != null) return null;
    if (rhs.ropeBody() != null) return null;
    const lhs_len = core.string.stringValueLen(lhs);
    const rhs_len = core.string.stringValueLen(rhs);
    if (lhs_len == 0 or rhs_len == 0) return null;
    // qjs OP_add_loc keeps a short flat accumulator FLAT: JS_ConcatStringInPlace
    // (rc==1 + malloc slack, qjs:4671-4703), else JS_ConcatString ->
    // JS_ConcatString2 while p1<=SHORT2_LEN && p2<=SHORT_LEN (qjs:5070-5075).
    // zjs flat strings are exact-sized FAM (no usable-size slack), so the
    // faithful adaptation is the JS_ConcatString1 copy leg via the existing
    // flat×flat path in stringAddStringsOwned (value_ops.zig:1127-1129).
    if (lhs_len <= core.string.String.rope_short2_len and rhs_len <= core.string.String.rope_short_len) return null;
    const rope = try core.string.String.createAccumulatorRope(rt, lhs, rhs);
    return rope.value();
}

Edge parity with JS_ConcatString: lhs>8192 & rhs<=512 -> rope (qjs:5075-5077 js_new_string_rope); rhs>512 -> rope (qjs falls out of the p2<=SHORT block); both small -> flat. Above 8192 the accumulator-tail O(1) machinery (tryAppendStringInPlace, checked FIRST at vm_arith.zig:676/788) resumes, matching qjs's rope regime for long accumulators.
